// ==UserScript==
// @name         x-slop-hide
// @namespace    https://github.com/StartupBros-com/x-slop-hide
// @version      0.2.0
// @description  Hides x.com posts by accounts on a self-updating AI-reply spam list. Hides only; muting is in the browser extension.
// @license      MIT
// @homepageURL  https://github.com/StartupBros-com/x-slop-hide
// @supportURL   https://github.com/StartupBros-com/x-slop-hide/issues
// @downloadURL  https://raw.githubusercontent.com/StartupBros-com/x-slop-hide/main/dist/x-slop-hide.user.js
// @updateURL    https://raw.githubusercontent.com/StartupBros-com/x-slop-hide/main/dist/x-slop-hide.user.js
// @match        https://x.com/*
// @match        https://twitter.com/*
// @match        https://mobile.x.com/*
// @match        https://mobile.twitter.com/*
// @run-at       document-start
// @grant        GM_getValue
// @grant        GM_setValue
// @grant        GM_xmlhttpRequest
// @grant        GM_registerMenuCommand
// @grant        GM_addValueChangeListener
// @connect      clankwall.vogel.dev
// ==/UserScript==
// Generated by scripts/build-userscript.mjs from src/. Edit the sources, then rebuild.
// ---- src/lib.js ----
// Shared, side-effect-free logic for x-slop-hide.
//
// Loaded three ways, so it must not depend on any one environment:
//   - content script: listed before content.js in manifest.json (shares the isolated world)
//   - background service worker: importScripts('lib.js')
//   - node tests: require() via module.exports
(function (root) {
  'use strict';

  // X handles: 1-15 of [A-Za-z0-9_], matched case-insensitively. Stored lowercased.
  const HANDLE_RE = /^[a-z0-9_]{1,15}$/;
  const PROFILE_HREF_RE = /^\/([A-Za-z0-9_]{1,15})$/;

  const DEFAULTS = Object.freeze({
    feedUrl: 'https://clankwall.vogel.dev/api/usernames.txt',
    refreshMinutes: 360,
    // After a failed attempt, wait this long before trying again.
    retryMinutes: 30,
    // How often an open userscript tab checks whether the list is due.
    checkMinutes: 15,
    timeoutMs: 20000,
    maxBytes: 1000000,
    maxHandles: 50000,
    // Refuse an update that drops below this fraction of the stored list:
    // a broken or truncated fetch must never silently switch hiding off.
    minShrinkRatio: 0.5,
    // The shrink guard only applies once the stored list is big enough for a
    // ratio to mean something.
    shrinkGuardFloor: 20,
    // Muting (off unless the user turns it on). Per UTC day: at most this many
    // mutes, and this many profile visits (an already-muted account costs a
    // visit, not a mute).
    muteDailyCap: 25,
    muteVisitCap: 50,
    // Minutes between visits, picked at random in this range. The alarm that
    // drives muting fires once a minute (the floor at Chrome 116).
    muteGapMinutes: [1, 3],
    // A mute tab still open after this long is closed and counted as a failure.
    muteTabTimeoutMs: 90000,
    // Mutes made since the last check of settings/muted/all. A background tab
    // renders only its first 9 rows (seen 2026-11-06), so check well before that.
    muteCheckEvery: 5,
    // Attempts at one account that end in a timeout or error before it is left alone.
    muteMaxAttempts: 2,
    // Accounts seen while browsing, muted ahead of the rest of the list.
    muteFrontMax: 50,
  });

  const STORAGE_KEYS = Object.freeze({
    list: 'xsh:list',
    settings: 'xsh:settings',
    mutes: 'xsh:mutes',
  });

  function normalizeHandle(raw) {
    if (raw == null) return null;
    let s = String(raw).trim();
    if (s.startsWith('@')) s = s.slice(1);
    s = s.toLowerCase();
    return HANDLE_RE.test(s) ? s : null;
  }

  // One handle per line. Blank lines and lines starting with '#' or '!' are
  // comments. Anything else that is not a valid handle counts as rejected.
  function parseList(text, opts) {
    const maxHandles = (opts && opts.maxHandles) || DEFAULTS.maxHandles;
    const seen = new Set();
    let rejected = 0;
    for (const line of String(text).split(/\r?\n/)) {
      const t = line.trim();
      if (!t || t.startsWith('#') || t.startsWith('!')) continue;
      const h = normalizeHandle(t);
      if (h) seen.add(h);
      else rejected++;
      if (seen.size > maxHandles) {
        return { handles: [], rejected, error: 'too many handles' };
      }
    }
    return { handles: [...seen].sort(), rejected, error: null };
  }

  function acceptUpdate(prevHandles, nextHandles, opts) {
    const ratio = (opts && opts.minShrinkRatio) || DEFAULTS.minShrinkRatio;
    const floor = (opts && opts.shrinkGuardFloor) || DEFAULTS.shrinkGuardFloor;
    if (!nextHandles || nextHandles.length === 0) return { ok: false, reason: 'empty list' };
    const prevCount = prevHandles ? prevHandles.length : 0;
    if (prevCount >= floor && nextHandles.length < prevCount * ratio) {
      return { ok: false, reason: `list shrank from ${prevCount} to ${nextHandles.length}` };
    }
    return { ok: true, reason: null };
  }

  function isDue(fetchedAt, now, refreshMinutes) {
    const minutes = refreshMinutes || DEFAULTS.refreshMinutes;
    if (!fetchedAt) return true;
    return now - fetchedAt >= minutes * 60 * 1000;
  }

  // Fetch and validate a feed. fetchImpl is the platform fetch (or a GM
  // wrapper). Never throws: returns { ok, handles, rejected } or { ok:false, reason }.
  async function fetchList(args) {
    const url = args.url || DEFAULTS.feedUrl;
    const fetchImpl = args.fetchImpl;
    const maxBytes = args.maxBytes || DEFAULTS.maxBytes;
    let res;
    try {
      const init = { cache: 'no-store', credentials: 'omit' };
      if (typeof AbortSignal !== 'undefined' && AbortSignal.timeout) {
        init.signal = AbortSignal.timeout(args.timeoutMs || DEFAULTS.timeoutMs);
      }
      res = await fetchImpl(url, init);
    } catch (e) {
      return { ok: false, reason: `network error: ${(e && e.message) || e}` };
    }
    if (!res || !res.ok) return { ok: false, reason: `HTTP ${res ? res.status : '?'}` };
    const ctype = (res.headers && res.headers.get && res.headers.get('content-type')) || '';
    if (/html/i.test(ctype)) return { ok: false, reason: `unexpected content-type ${ctype}` };
    let text;
    try {
      text = await res.text();
    } catch (e) {
      return { ok: false, reason: `read error: ${(e && e.message) || e}` };
    }
    if (text.length > maxBytes) return { ok: false, reason: `feed larger than ${maxBytes} bytes` };
    const parsed = parseList(text, { maxHandles: args.maxHandles });
    if (parsed.error) return { ok: false, reason: parsed.error };
    if (parsed.rejected > parsed.handles.length) {
      return { ok: false, reason: `feed is mostly not handles (${parsed.rejected} invalid lines)` };
    }
    const verdict = acceptUpdate(args.prevHandles, parsed.handles, args);
    if (!verdict.ok) return { ok: false, reason: verdict.reason };
    return { ok: true, handles: parsed.handles, rejected: parsed.rejected };
  }

  // Merge a fetch result into the stored record. A failed fetch keeps the
  // previous handles and fetchedAt and records why it failed.
  function nextRecord(prev, result, url, now) {
    const base = prev || { handles: [], fetchedAt: 0, source: url };
    if (result.ok) {
      return { handles: result.handles, fetchedAt: now, source: url, lastAttemptAt: now, lastError: null };
    }
    return Object.assign({}, base, { lastAttemptAt: now, lastError: result.reason });
  }

  // Commit a refresh against the record stored right now, not the one read
  // before the fetch. `seq` counts successful commits; startSeq is the value
  // read when the refresh began. If a newer refresh succeeded meanwhile, this
  // result is stale and is dropped (null: write nothing), so an older failed
  // or older successful fetch can never overwrite a newer list.
  function commitRecord(latest, result, url, startSeq, now) {
    const seq = (latest && latest.seq) || 0;
    if (seq > (startSeq || 0)) return null;
    const rec = nextRecord(latest, result, url, now);
    rec.seq = result.ok ? seq + 1 : seq;
    return rec;
  }

  // Due for a refresh: the list is older than the refresh interval, and the
  // last attempt (a failure, if the list is old) is older than the retry gap.
  function isRefreshDue(rec, now) {
    if (!isDue(rec && rec.fetchedAt, now, DEFAULTS.refreshMinutes)) return false;
    const last = rec && rec.lastAttemptAt;
    return !last || now - last >= DEFAULTS.retryMinutes * 60 * 1000;
  }

  function parseAllowlist(text) {
    const out = new Set();
    for (const tok of String(text || '').split(/[\s,]+/)) {
      const h = normalizeHandle(tok);
      if (h) out.add(h);
    }
    return out;
  }

  // X's own assistant. clankwall lists it, and people who tag it in a thread
  // may want its answer, so it has its own switch. Off (hidden) by default.
  const GROK = 'grok';

  // Handles that are never hidden: the user's allowlist, plus @grok when
  // showGrok is on. The switch adds only @grok, never a wider allow.
  function effectiveAllow(settings) {
    const s = settings || {};
    const out = parseAllowlist(s.allowlist);
    if (s.showGrok === true) out.add(GROK);
    return out;
  }

  // True when el sits inside a [role="link"] container below article, which is
  // how X renders a quoted post. Bounded at article so an ancestor outside the
  // post can never change the answer.
  function insideQuoteCard(el, article) {
    for (let n = el.parentElement; n && n !== article; n = n.parentElement) {
      if (n.getAttribute && n.getAttribute('role') === 'link') return true;
    }
    return false;
  }

  // The handle of the account that wrote this post, lowercased, or null.
  // It reads the first User-Name block that is not inside a quote card, so
  // quoted posts and @-mentions never count as the author.
  function authorHandleOf(article) {
    if (!article || !article.querySelectorAll) return null;
    for (const un of article.querySelectorAll('[data-testid="User-Name"]')) {
      if (insideQuoteCard(un, article)) continue;
      for (const a of un.querySelectorAll('a[href]')) {
        const m = PROFILE_HREF_RE.exec(a.getAttribute('href') || '');
        if (m) return m[1].toLowerCase();
      }
      return null;
    }
    return null;
  }

  // The handle whose profile or permalink this page is (/<handle>, /<handle>/status/…).
  function pageOwner(pathname) {
    const first = String(pathname || '').split('/')[1] || '';
    const h = first.toLowerCase();
    return HANDLE_RE.test(h) ? h : null;
  }

  function shouldHide(author, ctx) {
    if (!author || ctx.paused) return false;
    if (!ctx.list.has(author)) return false;
    if (ctx.allow && ctx.allow.has(author)) return false;
    // A listed account's own profile or post page was opened on purpose.
    if (ctx.owner && ctx.owner === author) return false;
    return true;
  }

  // ---------------------------------------------------------------- muting

  function utcDay(ms) {
    return new Date(ms).toISOString().slice(0, 10);
  }

  const norm = (s) => String(s || '').replace(/\s+/g, ' ').trim().toLowerCase();

  // Which item of a post's ⋯ menu to click, from the item labels X showed
  // (2026-11-06): "mute" on a listed account's post, "unmute" once muted,
  // "unfollow @h" when the user follows it, and a separate "mute this
  // conversation" that must never match. Returns
  //   { action: 'click', index }                 the one exact Mute item
  //   { action: 'done', status: 'already' }      already muted: nothing to click
  //   { action: 'refuse', status, reason, stopDay }
  function chooseMuteItem(items, handle) {
    const labels = (items || []).map(norm);
    const h = String(handle || '').toLowerCase();
    if (labels.some((l) => l === 'unmute' || l === `unmute @${h}`)) return { action: 'done', status: 'already' };
    if (labels.some((l) => l === `unfollow @${h}`)) {
      return { action: 'refuse', status: 'followed', reason: `you follow @${h}`, stopDay: false };
    }
    const hits = labels.map((l, i) => (l === 'mute' || l === `mute @${h}` ? i : -1)).filter((i) => i >= 0);
    if (hits.length !== 1) {
      return {
        action: 'refuse',
        status: 'refused',
        reason: `${hits.length} exact Mute items in the menu [${labels.join(' | ')}]`,
        stopDay: true,
      };
    }
    return { action: 'click', index: hits[0] };
  }

  // A fresh record of what muting has done: per account and per UTC day.
  function emptyMutes() {
    return { handles: {}, days: {}, front: [], nextAt: 0, sinceCheck: [] };
  }

  // Statuses that end work on an account. 'error' does not, until it has
  // happened muteMaxAttempts times, and neither does a first 'no-post': on
  // 2026-11-06, 3 of 4 profiles showed their first post before its ⋯ button.
  const SETTLED = new Set(['muted', 'already', 'followed', 'no-post', 'failed']);

  function isSettled(st) {
    if (!st || !SETTLED.has(st.status)) return false;
    if (st.status === 'no-post') return (st.attempts || 1) >= DEFAULTS.muteMaxAttempts;
    return true;
  }

  // Accounts to visit, in order: those seen while browsing first, then the
  // list, then accounts being tried again. Never the allowlist, never @grok
  // (muting it account-wide is a much bigger step than hiding its replies),
  // never an account already settled.
  function muteCandidates(listHandles, settings, rec) {
    const r = rec || emptyMutes();
    const allow = parseAllowlist(settings && settings.allowlist);
    const listed = new Set(listHandles || []);
    const fresh = [];
    const retry = [];
    const seen = new Set();
    for (const h of [...(r.front || []), ...(listHandles || [])]) {
      if (seen.has(h)) continue;
      seen.add(h);
      if (!listed.has(h) || h === GROK || allow.has(h)) continue;
      const st = r.handles[h];
      if (isSettled(st)) continue;
      (st ? retry : fresh).push(h);
    }
    return [...fresh, ...retry];
  }

  function dayOf(rec, today) {
    return (rec.days && rec.days[today]) || { mutes: 0, visits: 0, stopped: null };
  }

  // What today's caps leave. `stopped` is set when muting stopped itself for
  // the day (an unexpected menu, a wrong account, a mute not on the list).
  function muteBudget(rec, today) {
    const d = dayOf(rec || emptyMutes(), today);
    return {
      mutesLeft: Math.max(0, DEFAULTS.muteDailyCap - d.mutes),
      visitsLeft: Math.max(0, DEFAULTS.muteVisitCap - d.visits),
      stopped: d.stopped || null,
      mutes: d.mutes,
      visits: d.visits,
    };
  }

  // Fold one visit's outcome into the record (a new object). The visit was
  // already counted when its tab opened. Outcomes:
  //   muted        clicked the Mute item (toast text kept; confirmed later)
  //   already      the menu offered Unmute
  //   followed     the user follows the account: left alone
  //   no-post      no post by the account with a ⋯ button on its profile:
  //                tried once more, then left alone
  //   refused      the menu was not one we act on: stops muting for the day
  //   wrong-account, login   the tab is not logged in as the bound account: stops the day
  //   error        timeout, closed tab, a menu that did not open: retried, up to muteMaxAttempts
  function recordOutcome(rec, handle, outcome, now) {
    const r = structuredCloneish(rec || emptyMutes());
    const today = utcDay(now);
    const d = Object.assign({ mutes: 0, visits: 0, stopped: null }, r.days[today]);
    const prev = r.handles[handle] || {};
    const status = outcome.status;
    const entry = { status, at: now };
    if (outcome.reason) entry.reason = String(outcome.reason).slice(0, 200);
    if (status === 'muted') {
      d.mutes += 1;
      entry.toast = outcome.toast ? String(outcome.toast).slice(0, 120) : null;
      entry.confirmed = null;
      r.sinceCheck = [...(r.sinceCheck || []), handle];
    }
    if (status === 'error') {
      entry.attempts = (prev.attempts || 0) + 1;
      if (entry.attempts >= DEFAULTS.muteMaxAttempts) entry.status = 'failed';
    }
    if (status === 'no-post') entry.attempts = (prev.status === 'no-post' ? prev.attempts || 1 : 0) + 1;
    if (['refused', 'wrong-account', 'login'].includes(status)) {
      d.stopped = `@${handle}: ${status}${outcome.reason ? ` (${String(outcome.reason).slice(0, 160)})` : ''}`;
      // Not settled: the account is tried again on a later day.
      if (status !== 'refused') delete entry.status;
    }
    if (entry.status) r.handles[handle] = entry;
    r.front = (r.front || []).filter((h) => h !== handle);
    r.days[today] = d;
    return r;
  }

  // Fold a read of settings/muted/all's top rows into the record. Every mute
  // since the last check should be there; one that is not stops muting for
  // the day, because something is not as it looked.
  function recordCheck(rec, rows, now) {
    const r = structuredCloneish(rec || emptyMutes());
    const seen = new Set((rows || []).map((h) => String(h).toLowerCase()));
    const missing = [];
    for (const h of r.sinceCheck || []) {
      const e = r.handles[h];
      if (!e || e.status !== 'muted') continue;
      e.confirmed = seen.has(h);
      e.checkedAt = now;
      if (!e.confirmed) missing.push(h);
    }
    r.sinceCheck = [];
    if (missing.length) {
      const today = utcDay(now);
      const d = Object.assign({ mutes: 0, visits: 0, stopped: null }, r.days[today]);
      d.stopped = `not on settings/muted/all after muting: @${missing.join(', @')}`;
      r.days[today] = d;
    }
    return { rec: r, missing };
  }

  // A profile tab was opened: it counts against today's visit cap whatever it finds.
  function countVisit(rec, now) {
    const r = structuredCloneish(rec || emptyMutes());
    const today = utcDay(now);
    const d = Object.assign({ mutes: 0, visits: 0, stopped: null }, r.days[today]);
    d.visits += 1;
    r.days[today] = d;
    return r;
  }

  // Stop muting until the next UTC day, with the reason the popup shows.
  function stopDay(rec, now, reason) {
    const r = structuredCloneish(rec || emptyMutes());
    const today = utcDay(now);
    const d = Object.assign({ mutes: 0, visits: 0, stopped: null }, r.days[today]);
    d.stopped = String(reason).slice(0, 200);
    r.days[today] = d;
    return r;
  }

  // Put an account seen while browsing at the front of the queue.
  function noteSighting(rec, handle) {
    const r = structuredCloneish(rec || emptyMutes());
    const front = (r.front || []).filter((h) => h !== handle);
    front.unshift(handle);
    r.front = front.slice(0, DEFAULTS.muteFrontMax);
    return r;
  }

  function structuredCloneish(o) {
    return JSON.parse(JSON.stringify(o));
  }

  // Totals for the popup.
  function muteSummary(rec) {
    const r = rec || emptyMutes();
    const vals = Object.values(r.handles || {});
    return {
      muted: vals.filter((e) => e.status === 'muted').length,
      confirmed: vals.filter((e) => e.status === 'muted' && e.confirmed === true).length,
      notFound: vals.filter((e) => e.status === 'muted' && e.confirmed === false).length,
      already: vals.filter((e) => e.status === 'already').length,
      followed: vals.filter((e) => e.status === 'followed').length,
      skipped: vals.filter((e) => e.status === 'no-post' || e.status === 'failed').length,
    };
  }

  const api = {
    HANDLE_RE,
    DEFAULTS,
    STORAGE_KEYS,
    normalizeHandle,
    parseList,
    acceptUpdate,
    isDue,
    fetchList,
    nextRecord,
    commitRecord,
    isRefreshDue,
    parseAllowlist,
    GROK,
    effectiveAllow,
    insideQuoteCard,
    authorHandleOf,
    pageOwner,
    shouldHide,
    utcDay,
    chooseMuteItem,
    emptyMutes,
    muteCandidates,
    muteBudget,
    recordOutcome,
    recordCheck,
    countVisit,
    stopDay,
    noteSighting,
    muteSummary,
  };
  root.XSlopHide = api;
  if (typeof module === 'object' && module && module.exports) module.exports = api;
})(typeof globalThis !== 'undefined' ? globalThis : this);

// ---- src/userscript-adapter.js ----
// Userscript adapter: supplies state to content.js through Greasemonkey APIs
// when the extension is not installed. Included only in dist/x-slop-hide.user.js.
/* global GM_getValue, GM_setValue, GM_xmlhttpRequest, GM_registerMenuCommand, GM_addValueChangeListener, setInterval */
(function () {
  'use strict';
  const L = globalThis.XSlopHide;
  const K = L.STORAGE_KEYS;
  const subscribers = [];

  const read = () => ({ list: GM_getValue(K.list, null), settings: GM_getValue(K.settings, {}) });
  const notify = () => {
    const s = read();
    for (const cb of subscribers) cb(s);
  };

  // A fetch-shaped wrapper so lib.fetchList validates exactly as the extension does.
  function gmFetch(url) {
    return new Promise((resolve, reject) => {
      GM_xmlhttpRequest({
        method: 'GET',
        url,
        anonymous: true,
        timeout: L.DEFAULTS.timeoutMs,
        onload: (r) => {
          const ctype = /^content-type:\s*(.*)$/im.exec(r.responseHeaders || '');
          resolve({
            ok: r.status >= 200 && r.status < 300,
            status: r.status,
            headers: { get: (name) => (/^content-type$/i.test(name) && ctype ? ctype[1].trim() : null) },
            text: () => Promise.resolve(r.responseText || ''),
          });
        },
        onerror: () => reject(new Error('request failed')),
        ontimeout: () => reject(new Error('timed out')),
      });
    });
  }

  // One refresh at a time per tab. Tabs share GM storage, so the commit
  // re-reads the stored list and drops a result a newer refresh superseded.
  let inflight = null;
  function refresh(force) {
    if (inflight) return inflight;
    const s = read();
    const prev = s.list;
    if (!force && !L.isRefreshDue(prev, Date.now())) return Promise.resolve();
    const url = (s.settings && s.settings.feedUrl) || L.DEFAULTS.feedUrl;
    const startSeq = (prev && prev.seq) || 0;
    inflight = L.fetchList({ url, fetchImpl: gmFetch, prevHandles: prev && prev.handles })
      .then((result) => {
        const record = L.commitRecord(GM_getValue(K.list, null), result, url, startSeq, Date.now());
        if (record) GM_setValue(K.list, record);
        notify();
      })
      .finally(() => (inflight = null));
    return inflight;
  }

  function patchSettings(patch) {
    GM_setValue(K.settings, Object.assign({}, GM_getValue(K.settings, {}), patch));
    notify();
  }

  globalThis.XSlopHideAdapter = {
    load: () => Promise.resolve(read()),
    subscribe(cb) {
      subscribers.push(cb);
    },
  };

  if (typeof GM_addValueChangeListener === 'function') {
    GM_addValueChangeListener(K.list, (_n, _o, _v, remote) => remote && notify());
    GM_addValueChangeListener(K.settings, (_n, _o, _v, remote) => remote && notify());
  }
  if (typeof GM_registerMenuCommand === 'function') {
    GM_registerMenuCommand('Pause / resume hiding', () => patchSettings({ paused: !read().settings.paused }));
    GM_registerMenuCommand('Show / hide @grok', () => patchSettings({ showGrok: read().settings.showGrok !== true }));
    GM_registerMenuCommand('Refresh list now', () => refresh(true));
    GM_registerMenuCommand('Edit always-show list', () => {
      const cur = read().settings.allowlist || '';
      const next = prompt('Accounts to always show (space or comma separated):', cur.replace(/\n/g, ' '));
      if (next != null) patchSettings({ allowlist: [...L.parseAllowlist(next)].sort().join('\n') });
    });
  }
  // A tab can stay open for days through in-app navigation: check whether
  // the list is due on a timer, and again when the tab comes back into view
  // (background tabs may throttle or suspend timers).
  refresh(false);
  setInterval(() => refresh(false), L.DEFAULTS.checkMinutes * 60 * 1000);
  document.addEventListener('visibilitychange', () => {
    if (document.visibilityState === 'visible') refresh(false);
  });
})();

// ---- src/content.js ----
// x-slop-hide content script: hides x.com timeline cells whose post author is
// on the list. In the user's own tabs it never clicks anything.
//
// Muting, when the user has turned it on, happens only in a tab the background
// worker opened for one job (see runJob below): there it clicks a post's ⋯ and
// X's own Mute item, then reports back, and the worker closes the tab. It never
// calls X's API.
//
// State comes from an adapter: the extension adapter below (chrome.storage,
// filled by background.js), or globalThis.XSlopHideAdapter when the userscript
// build supplies one. The userscript adapter has no jobs, so it only hides.
(function () {
  'use strict';
  const L = globalThis.XSlopHide;
  if (!L) return;

  const ATTR = 'data-xsh-hidden';
  const ARTICLE = 'article[data-testid="tweet"]';
  const CELL = '[data-testid="cellInnerDiv"]';

  let list = new Set();
  let allow = new Set();
  let paused = false;
  let muting = false;
  let lastPath = location.pathname;
  const hiddenPosts = new Set(); // distinct posts hidden in this tab
  const hiddenAuthors = new Set();

  function injectStyle() {
    if (document.getElementById('xsh-style')) return;
    const st = document.createElement('style');
    st.id = 'xsh-style';
    st.textContent = `[${ATTR}]{display:none!important}`;
    (document.head || document.documentElement).appendChild(st);
  }

  function postKey(article) {
    const t = article.querySelector('a[href*="/status/"] time');
    const a = t && t.closest('a');
    return (a && a.getAttribute('href')) || null;
  }

  function evaluate(article, owner) {
    const author = L.authorHandleOf(article);
    const cell = article.closest(CELL) || article;
    const hide = L.shouldHide(author, { list, allow, owner, paused });
    if (hide) {
      if (cell.getAttribute(ATTR) !== author) cell.setAttribute(ATTR, author);
      // Seen while browsing: muted ahead of the rest of the list.
      if (muting && !hiddenAuthors.has(author) && adapter.noteSighting) adapter.noteSighting(author);
      hiddenAuthors.add(author);
      const k = postKey(article);
      if (k) hiddenPosts.add(k);
    } else if (cell.hasAttribute(ATTR)) {
      cell.removeAttribute(ATTR);
    }
  }

  function rescanAll() {
    const owner = L.pageOwner(location.pathname);
    for (const art of document.querySelectorAll(ARTICLE)) evaluate(art, owner);
    // Cells hidden earlier whose post has since been replaced or unlisted.
    for (const cell of document.querySelectorAll(`[${ATTR}]`)) {
      const art = cell.matches(ARTICLE) ? cell : cell.querySelector(ARTICLE);
      if (!art) cell.removeAttribute(ATTR);
    }
  }

  function onMutations(records) {
    if (location.pathname !== lastPath) {
      lastPath = location.pathname;
      rescanAll();
      return;
    }
    const owner = L.pageOwner(lastPath);
    const touched = new Set();
    const dirtyCells = new Set();
    for (const r of records) {
      if (r.type === 'attributes') {
        // An href rewritten in place, as when a recycled node gets a new post.
        const host = r.target && r.target.nodeType === 1 ? r.target.closest(ARTICLE) : null;
        if (host) touched.add(host);
        continue;
      }
      // Removed nodes no longer have a useful parent. Revisit their surviving
      // target article or hidden cell after the whole mutation batch settles.
      if (r.removedNodes && r.removedNodes.length && r.target && r.target.nodeType === 1) {
        const host = r.target.closest(ARTICLE);
        if (host) touched.add(host);
        const cell = r.target.closest(CELL);
        if (cell && cell.hasAttribute(ATTR)) dirtyCells.add(cell);
      }
      for (const n of r.addedNodes || []) {
        if (n.nodeType !== 1) continue;
        // n is a post, sits inside one (X fills the author block in late), or holds some.
        const host = n.closest(ARTICLE);
        if (host) touched.add(host);
        // One subtree walk finds posts and previously hidden, reinserted cells.
        if (n.hasAttribute(ATTR)) dirtyCells.add(n);
        for (const element of n.querySelectorAll(`${ARTICLE}, [${ATTR}]`)) {
          if (!host && element.matches(ARTICLE)) touched.add(element);
          if (element.hasAttribute(ATTR)) dirtyCells.add(element);
        }
      }
    }
    for (const cell of dirtyCells) {
      if (!document.contains(cell)) continue;
      const articles = cell.matches(ARTICLE) ? [cell] : cell.querySelectorAll(ARTICLE);
      if (!articles.length) cell.removeAttribute(ATTR);
      else for (const art of articles) touched.add(art);
    }
    // A node added then removed in the same batch must not affect live state or stats.
    for (const art of touched) if (document.contains(art)) evaluate(art, owner);
  }

  function applyState(s) {
    list = new Set((s.list && s.list.handles) || []);
    allow = L.effectiveAllow(s.settings);
    paused = !!(s.settings && s.settings.paused);
    muting = !!(s.settings && s.settings.muteEnabled);
    rescanAll();
  }

  // Who this tab is logged in as: { me } from the sidebar's profile link,
  // { login: true } when x.com shows a login button, null while still loading.
  function whoAmI() {
    if (document.querySelector('[data-testid="loginButton"]')) return { login: true };
    const a = document.querySelector('[data-testid="AppTabBar_Profile_Link"]');
    const m = a && /^\/([A-Za-z0-9_]{1,15})$/.exec(a.getAttribute('href') || '');
    return m ? { me: m[1].toLowerCase() } : null;
  }

  function stats() {
    const who = whoAmI();
    return {
      listed: list.size,
      paused,
      me: (who && who.me) || null,
      hiddenNow: document.querySelectorAll(`[${ATTR}]`).length,
      hiddenPosts: hiddenPosts.size,
      hiddenAuthors: [...hiddenAuthors].sort(),
    };
  }

  // ------------------------------------------------------------ mute jobs

  const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
  const textOf = (el) => (el.textContent || '').replace(/\s+/g, ' ').trim();

  async function waitFor(fn, ms, step) {
    const end = Date.now() + ms;
    for (;;) {
      const v = fn();
      if (v) return v;
      if (Date.now() >= end) return null;
      await sleep(step || 500);
    }
  }

  // How long to wait for the page to show who is logged in, a post, or rows.
  const waitMs = (job) => job.waitMs || 20000;

  // The job's tab must be logged in as the account muting was turned on for.
  async function wrongAccount(job) {
    const who = await waitFor(whoAmI, waitMs(job));
    if (!who) return { status: 'error', reason: 'the page never showed who is logged in' };
    if (who.login) return { status: 'login', reason: 'x.com shows a login button' };
    if (who.me !== job.account) return { status: 'wrong-account', reason: `logged in as @${who.me}, not @${job.account}` };
    return null;
  }

  // On x.com/<handle>: open the ⋯ menu of a post the account wrote (reposts
  // and quoted posts do not count) and click X's own Mute item. Tested with
  // synthetic clicks on 2026-11-06, including in a background tab that drew no
  // frames. A menu we decline stays open: the worker closes the tab.
  async function muteJob(job) {
    const h = job.handle;
    const bad = await wrongAccount(job);
    if (bad) return bad;
    // A post appears a few seconds before its ⋯ button does (seen on 3 of 4
    // profiles on 2026-11-06), so wait for one that has the button.
    const own = () => [...document.querySelectorAll(ARTICLE)].filter((a) => L.authorHandleOf(a) === h);
    const caret = await waitFor(() => {
      for (const a of own()) {
        const c = a.querySelector('[data-testid="caret"]');
        if (c) return c;
      }
      return null;
    }, waitMs(job));
    if (!caret) {
      return { status: 'no-post', reason: own().length ? 'its posts have no ⋯ button' : 'no post by the account on its profile' };
    }
    caret.click();
    const menu = await waitFor(() => document.querySelector('[role="menu"]'), 5000, 300);
    if (!menu) return { status: 'error', reason: 'the ⋯ menu did not open' };
    await sleep(300); // the items arrive just after the menu node
    const items = [...menu.querySelectorAll('[role="menuitem"]')];
    const pick = L.chooseMuteItem(items.map(textOf), h);
    if (pick.action === 'done') return { status: pick.status };
    if (pick.action === 'refuse') return { status: pick.status, reason: pick.reason };
    items[pick.index].click();
    const sheet = () => document.querySelector('[data-testid="confirmationSheetDialog"]');
    const toast = () => {
      const t = document.querySelector('[data-testid="toast"]');
      return t && textOf(t) ? t : null;
    };
    await waitFor(() => sheet() || toast(), 4000, 250);
    if (sheet()) return { status: 'refused', reason: 'X asked for a confirmation; left it unanswered' };
    const t = toast();
    return { status: 'muted', toast: t ? textOf(t) : null };
  }

  function mutedRows() {
    const out = [];
    for (const cell of document.querySelectorAll('[data-testid="UserCell"]')) {
      const a = cell.querySelector('a[href]');
      const m = a && /^\/([A-Za-z0-9_]{1,15})$/.exec(a.getAttribute('href') || '');
      if (m) out.push(m[1].toLowerCase());
    }
    return out;
  }

  // On x.com/settings/muted/all: the rows it renders, newest mute first. A
  // background tab renders only the first 9 or so and loads no more on scroll
  // (seen 2026-11-06), which is why the worker checks every few mutes.
  async function checkJob(job) {
    const bad = await wrongAccount(job);
    if (bad) return bad;
    const any = await waitFor(() => mutedRows().length || document.querySelector('[data-testid="emptyState"]'), waitMs(job));
    if (!any) return { status: 'error', reason: 'settings/muted/all showed no rows' };
    // Rows arrive in batches: read them once the count has held for a second.
    let n = mutedRows().length;
    for (let i = 0; i < 5; i++) {
      await sleep(1000);
      const m = mutedRows().length;
      if (m === n) break;
      n = m;
    }
    return { status: 'checked', rows: mutedRows() };
  }

  async function runJob(job) {
    const work = job.kind === 'mute' ? muteJob(job) : job.kind === 'check' ? checkJob(job) : null;
    if (!work) return;
    let timer = null;
    const timeout = new Promise((r) => {
      timer = setTimeout(() => r({ status: 'error', reason: 'timed out in the page' }), job.pageTimeoutMs || 60000);
    });
    let result;
    try {
      result = await Promise.race([work, timeout]);
    } catch (e) {
      result = { status: 'error', reason: String((e && e.message) || e) };
    } finally {
      clearTimeout(timer);
    }
    return adapter.reportJob(Object.assign({ id: job.id }, result));
  }

  function extensionAdapter() {
    const K = L.STORAGE_KEYS;
    const read = () =>
      chrome.storage.local.get([K.list, K.settings]).then((o) => ({ list: o[K.list], settings: o[K.settings] }));
    return {
      load: read,
      subscribe(cb) {
        chrome.storage.onChanged.addListener((changes, area) => {
          if (area === 'local' && (changes[K.list] || changes[K.settings])) read().then(cb);
        });
      },
      serveStats(fn) {
        chrome.runtime.onMessage.addListener((msg, _sender, sendResponse) => {
          if (msg && msg.type === 'xsh:stats') sendResponse(fn());
        });
      },
      // The worker answers with a job only for a tab it opened for one.
      getJob: () => chrome.runtime.sendMessage({ type: 'xsh:job' }).catch(() => null),
      reportJob: (result) => chrome.runtime.sendMessage({ type: 'xsh:job-result', result }).catch(() => {}),
      noteSighting: (handle) => chrome.runtime.sendMessage({ type: 'xsh:sighting', handle }).catch(() => {}),
    };
  }

  const adapter =
    globalThis.XSlopHideAdapter ||
    (typeof chrome !== 'undefined' && chrome.storage && chrome.runtime && chrome.runtime.id ? extensionAdapter() : null);
  if (!adapter) return;

  injectStyle();
  new MutationObserver(onMutations).observe(document, {
    childList: true,
    subtree: true,
    attributes: true,
    attributeFilter: ['href'],
  });
  adapter.subscribe(applyState);
  if (adapter.serveStats) adapter.serveStats(stats);
  adapter.load().then(applyState);
  if (adapter.getJob && adapter.reportJob) adapter.getJob().then((job) => job && runJob(job));

  // Exposed for the userscript adapter and the live test harness only.
  globalThis.XSlopHideContent = { stats, rescanAll, applyState, runJob };
})();
